from decimal import Decimal
from typing import Any


def _value(row: dict | None, column: str) -> Any:
    if row is None:
        return ""
    return row.get(column, "")


def _number(value: Any) -> Decimal:
    if value == "":
        return Decimal("0")
    return Decimal(str(value))


def _lookup(
    tables: dict | None,
    table: str,
    key_col: str,
    key_val: Any,
    out_col: str,
) -> Any:
    if tables is None:
        return ""

    for row in tables.get(table, []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_col, "") == key_val:
            return row.get(out_col, "")
    return ""


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    errors: list[dict] = []

    def fail(code: str, message: str) -> None:
        errors.append(
            {
                "code": code,
                "message": message,
                "severity": "BLOCK",
            }
        )

    if table == "ORD_HEADER":
        # ORD-001
        if event in ("INSERT", "UPDATE"):
            discount = _number(_value(record, "DISC_PCT"))
            if not (discount >= Decimal("0") and discount <= Decimal("100")):
                fail("E5001", "Discount out of range")

        # ORD-002
        if event == "UPDATE":
            discount = _number(_value(record, "DISC_PCT"))
            owner_uid = _value(record, "OWNER_UID")
            passes = not (
                discount > Decimal("20")
                and _lookup(
                    tables, "USR_MASTER", "USR_ID", owner_uid, "ROLE_ID"
                ) != "MGR"
                and _lookup(
                    tables, "USR_MASTER", "USR_ID", owner_uid, "ROLE_ID"
                ) != "ADMIN"
            )
            if not passes:
                fail("E5002", "Discount over 20 percent requires manager role")

        # ORD-003
        if event == "UPDATE":
            passes = not (
                _value(old, "STAT_CD") == "I"
                and _value(record, "STAT_CD") != "I"
                and _value(record, "STAT_CD") != "X"
            )
            if not passes:
                fail("E5003", "Invoiced order can only be cancelled")

    elif table == "ORD_LINE":
        # ORD-004
        if event in ("INSERT", "UPDATE"):
            if not (_number(_value(record, "QTY")) > Decimal("0")):
                fail("E5004", "Quantity must be positive")

        # ORD-005
        if event == "INSERT":
            product_id = _value(record, "PROD_ID")
            if (
                _lookup(
                    tables,
                    "PROD_MASTER",
                    "PROD_ID",
                    product_id,
                    "ACTIVE_FLG",
                )
                != "Y"
            ):
                fail("E5005", "Product not active")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
